abstract class ParticipantApi { Future<Map<String,dynamic>> exchange(String invitation); Future<Map<String,dynamic>> session(); Future<Map<String,dynamic>> legalDocuments(); Future<void> consent(Map<String,String> documentHashes); Future<void> logout(); }
class ApiError implements Exception { const ApiError(this.message); final String message; }
const _allowLocalQaHttp = bool.fromEnvironment('PCIP_LOCAL_QA');
// Matches the deployed PCIP BASE_URL in .github/workflows/deploy-azure.yml.
const _configuredReleaseApiBase = String.fromEnvironment('PCIP_API_BASE_URL',defaultValue:'https://citizencentric.co.uk');
const _configuredDebugApiBase = String.fromEnvironment('PCIP_QA_API_BASE_URL');
bool _isQaHttpBase(Uri base) => kDebugMode && _allowLocalQaHttp && base.scheme == 'http' && (base.host == 'localhost' || base.host == '10.0.2.2');
String selectedApiBaseValue({required bool debugMode,required String releaseValue,required String debugValue}) => debugMode && debugValue.isNotEmpty ? debugValue : releaseValue;
Uri? configuredApiBase(){final configured=selectedApiBaseValue(debugMode:kDebugMode,releaseValue:_configuredReleaseApiBase,debugValue:_configuredDebugApiBase);final base=Uri.tryParse(configured);if(base==null||base.host.isEmpty)return null;if(base.scheme!='https'&&!_isQaHttpBase(base))return null;return base.replace(path:base.path.replaceFirst(RegExp(r'/+$'),''));}
bool allowsApiBase(Uri base){final configured=configuredApiBase();return configured!=null&&base.scheme==configured.scheme&&base.host==configured.host&&base.port==configured.port&&base.path.replaceFirst(RegExp(r'/+$'),'')==configured.path.replaceFirst(RegExp(r'/+$'),'');}
String? invitationCodeError(String value)=>value.trim().isEmpty?'Enter your invitation code to continue.':null;
bool invitationRequiresConsent(Map<String,dynamic>? session){final action=session?['next_action'];if(action is String)return action=='consent_required';final invitation=session?['invitation'];return invitation is Map&&invitation['accepted_at']==null;}
bool invitationRequiresStudyDocuments(Map<String,dynamic>? session){final invitation=session?['invitation'];return invitation is Map&&invitation['requires_study_documents']==true;}
String participantDateTime(Object? value) { final parsed=DateTime.tryParse(value?.toString()??''); if(parsed==null)return 'Date unavailable'; final local=parsed.toLocal(); String two(int number)=>number.toString().padLeft(2,'0'); return '${two(local.day)}/${two(local.month)}/${local.year} at ${two(local.hour)}:${two(local.minute)}'; }
class Api implements ParticipantApi {
  Api(this.base,this.token); final Uri base; final String? token;
  // ignore: use_null_aware_elements
  Future<Map<String,dynamic>> request(String method,String path,{Object? body,String? idempotencyKey}) async { if(!allowsApiBase(base)) throw const ApiError('A secure service connection is unavailable.'); final r=http.Request(method,base.resolve(path))..headers.addAll({'Accept':'application/json','Content-Type':'application/json',if(token case final value?) 'Authorization':'Bearer $value',if(idempotencyKey case final key?) 'Idempotency-Key':key})..body=body==null?'':jsonEncode(body); final x=await http.Response.fromStream(await r.send()); if(x.statusCode==401) throw const ApiError('Your session has ended.'); if(x.statusCode==400&&path=='/api/v1/participant/session/exchange') throw const ApiError('This invitation is invalid or has expired.'); if(x.statusCode<200||x.statusCode>299) throw const ApiError('We could not complete that safely. Please try again.'); return Map<String,dynamic>.from(jsonDecode(x.body)); }
  @override Future<Map<String,dynamic>> exchange(String invitation)=>request('POST','/api/v1/participant/session/exchange',body:{'invitation_token':invitation});
  @override Future<Map<String,dynamic>> session()=>request('GET','/api/v1/participant/session');
  @override Future<Map<String,dynamic>> legalDocuments()=>request('GET','/api/v1/participant/legal-documents');
  @override Future<void> consent(Map<String,String> documentHashes) async { await request('POST','/api/v1/participant/consent',body:{'consent':true,'document_hashes':documentHashes}); }
  @override Future<void> logout() async { await request('DELETE','/api/v1/participant/session'); }
  Future<List<dynamic>> activities() async => (await request('GET','/api/v1/participant/activities'))['data'] as List<dynamic>;
  Future<void> draft(int id,String answer,String key) async { await request('PUT','/api/v1/participant/activities/$id/draft',body:{'answer':answer,'choices':[]},idempotencyKey:key); }
  Future<void> submit(int id,String answer,String key) async { await request('POST','/api/v1/participant/activities/$id/submit',body:{'answer':answer,'choices':[]},idempotencyKey:key); }
  Future<Map<String,dynamic>> profile() => request('GET','/api/v1/participant/profile');
  Future<Map<String,dynamic>> updatePreference(String value,String key) => request('PUT','/api/v1/participant/profile',body:{'communication_preference':value},idempotencyKey:key);
  Future<List<dynamic>> history() async => (await request('GET','/api/v1/participant/submissions'))['data'] as List<dynamic>;
  Future<List<dynamic>> messages() async => (await request('GET','/api/v1/participant/messages'))['data'] as List<dynamic>;
  Future<Map<String,dynamic>> sendMessage(String body,String key) => request('POST','/api/v1/participant/messages',body:{'body':body},idempotencyKey:key);
  Future<Map<String,dynamic>> uploadPhoto(int activityId,XFile photo,String key) async { final r=http.MultipartRequest('POST',base.resolve('/api/v1/participant/activities/$activityId/evidence-uploads'))..headers.addAll({'Accept':'application/json',if(token case final value?)'Authorization':'Bearer $value','Idempotency-Key':key})..fields['activity_id']='$activityId'..files.add(await http.MultipartFile.fromPath('file',photo.path,filename:photo.name));final x=await http.Response.fromStream(await r.send());if(x.statusCode==401)throw const ApiError('Your session has ended.');if(x.statusCode<200||x.statusCode>299)throw const ApiError('We could not upload that photo. Please try again.');return Map<String,dynamic>.from(jsonDecode(x.body));}
  Future<Map<String,dynamic>> evidenceStatus(int id)=>request('GET','/api/v1/participant/evidence/$id/status');
  Future<Map<String,dynamic>> uploadDocument(int activityId,String path,String name,String key) async { final r=http.MultipartRequest('POST',base.resolve('/api/v1/participant/activities/$activityId/evidence-uploads'))..headers.addAll({'Accept':'application/json',if(token case final value?)'Authorization':'Bearer $value','Idempotency-Key':key})..fields['activity_id']='$activityId'..files.add(await http.MultipartFile.fromPath('file',path,filename:name));final x=await http.Response.fromStream(await r.send());if(x.statusCode==401)throw const ApiError('Your session has ended.');if(x.statusCode<200||x.statusCode>299)throw const ApiError('We could not upload that document. Please try again.');return Map<String,dynamic>.from(jsonDecode(x.body));}
  Future<Map<String,dynamic>> uploadAudio(int activityId,String path,String key)=>uploadDocument(activityId,path,'voice-diary.m4a',key);
  Future<Map<String,dynamic>> withdraw(String key)=>request('POST','/api/v1/participant/privacy/withdrawal-requests',body:{'scope':'study','confirmed':true},idempotencyKey:key);
  Future<Map<String,dynamic>> deletion(String key,String scope)=>request('POST','/api/v1/participant/privacy/deletion-requests',body:{'mode_preference':'delete','scope':scope,'confirmed':true},idempotencyKey:key);
}
Future<void> clearParticipantCache(SharedPreferences prefs) async { final sensitive=prefs.getKeys().where((key)=>key=='cached_profile'||key=='cached_history'||key=='cached_messages'||key=='submission_queue'||key.startsWith('draft_')).toList(); for(final key in sensitive){await prefs.remove(key);} try{final voice=File('${(await getTemporaryDirectory()).path}/voice-diary.m4a');if(await voice.exists())await voice.delete();}catch(_){} }
Future<Map<String,dynamic>?> cachedObject(String key) async { final prefs=await SharedPreferences.getInstance(); final value=prefs.getString(key); if(value==null)return null; try{final decoded=jsonDecode(value);if(decoded is Map)return Map<String,dynamic>.from(decoded);}catch(_){}await prefs.remove(key);return null; }
Future<List<dynamic>?> cachedList(String key) async { final prefs=await SharedPreferences.getInstance(); final value=prefs.getString(key); if(value==null)return null; try{final decoded=jsonDecode(value);if(decoded is List)return decoded;}catch(_){}await prefs.remove(key);return null; }
class SessionStore { SessionStore(this.storage); final FlutterSecureStorage storage; Future<void> save(String url,String token)=>Future.wait([storage.write(key:'api_url',value:url),storage.write(key:'access_token',value:token)]); Future<(String,String)?> read() async { final u=await storage.read(key:'api_url');final t=await storage.read(key:'access_token');return u==null||t==null?null:(u,t); } Future<void> clear() async { await storage.deleteAll(); await clearParticipantCache(await SharedPreferences.getInstance()); } }
final _store=SessionStore(FlutterSecureStorage());
void main()=>runApp(ParticipantApp());
class ParticipantApp extends StatefulWidget { ParticipantApp({super.key,SessionStore? store,this.factory}):store=store??_store; final SessionStore store; final ParticipantApi Function(String,String?)? factory; @override State<ParticipantApp> createState()=>_ParticipantAppState(); }
class _ParticipantAppState extends State<ParticipantApp> { ParticipantApi? api; Map<String,dynamic>? session; List<Map<String,dynamic>> studyDocuments=[]; bool busy=true,documentsLoading=false; String? error,documentsError;
  ParticipantApi make(String u,String? t)=>widget.factory?.call(u,t)??Api(Uri.parse(u),t);
  @override void initState(){super.initState();restore();}
  Future<void> loadStudyDocuments() async {if(!invitationRequiresStudyDocuments(session)){studyDocuments=[];documentsError=null;return;}documentsLoading=true;documentsError=null;if(mounted)setState((){});try{final result=await api!.legalDocuments();final documents=(result['documents'] as List? ?? const []).map((item)=>Map<String,dynamic>.from(item as Map)).toList();final types=documents.map((item)=>item['document_type'].toString()).toSet();if(!types.containsAll({'participant_information','privacy_notice','consent_text'}))throw const ApiError('The study consent documents are incomplete.');studyDocuments=documents;}on ApiError catch(_){studyDocuments=[];documentsError='We could not load this study’s consent documents. Your consent has not been submitted.';}catch(_){studyDocuments=[];documentsError='We could not load this study’s consent documents. Your consent has not been submitted.';}documentsLoading=false;if(mounted)setState((){});}
  Future<void> refreshSession() async {session=await api!.session();if(invitationRequiresConsent(session))await loadStudyDocuments();else {studyDocuments=[];documentsError=null;}}
  Future<void> restore() async { final saved=await widget.store.read(); if(saved!=null){try{api=make(saved.$1,saved.$2);await refreshSession();}catch(_){await widget.store.clear();api=null;}}if(mounted)setState(()=>busy=false); }
  Future<void> join(String invitation) async { final codeError=invitationCodeError(invitation);if(codeError!=null){error=codeError;if(mounted)setState((){});return;}final base=configuredApiBase();if(base==null){error='This app is not configured to connect securely. Please contact your research team.';if(mounted)setState((){});return;}try{final first=make(base.toString(),null);final result=await first.exchange(invitation.trim());final token=(result['session'] as Map)['access_token'] as String;await widget.store.save(base.toString(),token);api=make(base.toString(),token);await refreshSession();error=null;}on ApiError catch(e){error=e.message;}catch(_){error='We could not connect. Please try again.';}if(mounted)setState((){}); }
  Future<void> accept(Map<String,String> documentHashes) async { try{await api!.consent(documentHashes);await refreshSession();error=null;}on ApiError catch(e){error=e.message;}if(mounted)setState((){}); }
  Future<void> signOut() async { try{await api?.logout();}catch(_){}await widget.store.clear();if(mounted)setState((){api=null;session=null;error=null;}); }
  @override Widget build(BuildContext c){if(busy)return const MaterialApp(home:Scaffold(body:Center(child:CircularProgressIndicator(semanticsLabel:'Loading your secure session'))));if(api==null)return MaterialApp(home:Invite(error:error,onJoin:join));final participant=Map<String,dynamic>.from(session!['participant']);if(invitationRequiresConsent(session))return MaterialApp(home:Consent(error:error,documents:studyDocuments,documentsRequired:invitationRequiresStudyDocuments(session),documentsLoading:documentsLoading,documentsError:documentsError,onRetry:loadStudyDocuments,onAccept:accept));return MaterialApp(home:Home(api:api! as Api,name:participant['display_name'] as String,onLogout:signOut));}
}
