enum SyncState { waiting, sending, sent, needsAttention }
class Queue {
  static const _key='submission_queue';
  static Future<void> add(Map<String,dynamic> entry) async { final p=await SharedPreferences.getInstance();final rows=p.getStringList(_key)??[];if(rows.any((row)=>jsonDecode(row)['idempotency_key']==entry['idempotency_key']))return;rows.add(jsonEncode({...entry,'attempts':0,'next_attempt_at':DateTime.now().toIso8601String()}));await p.setStringList(_key,rows); }
  static Future<int> count()async=>(await SharedPreferences.getInstance()).getStringList(_key)?.length??0;
  static Duration backoff(int attempts)=>Duration(seconds:(1<<attempts.clamp(0,6)));
  static Future<SyncState> replay(Api api,{DateTime? now}) async { final p=await SharedPreferences.getInstance();final rows=p.getStringList(_key)??[];final retained=<String>[];var state=SyncState.sent;final clock=now??DateTime.now();for(final row in rows){Map<String,dynamic> item;try{item=Map<String,dynamic>.from(jsonDecode(row));}catch(_){retained.add(row);state=SyncState.needsAttention;continue;}final due=DateTime.tryParse(item['next_attempt_at']??'')??clock;if(due.isAfter(clock)){retained.add(row);state=SyncState.waiting;continue;}try{await api.submit(item['activity_id'] as int,item['answer'] as String,item['idempotency_key'] as String);}on ApiError catch(e){if(e.message=='Your session has ended.'){retained.add(row);state=SyncState.needsAttention;}else{final attempts=(item['attempts'] as int? ??0)+1;item['attempts']=attempts;item['next_attempt_at']=clock.add(backoff(attempts)).toIso8601String();retained.add(jsonEncode(item));state=SyncState.waiting;}}catch(_){final attempts=(item['attempts'] as int? ??0)+1;item['attempts']=attempts;item['next_attempt_at']=clock.add(backoff(attempts)).toIso8601String();retained.add(jsonEncode(item));state=SyncState.waiting;}}await p.setStringList(_key,retained);return state; }
}
class Activities extends StatefulWidget{const Activities({super.key,required this.api});final Api api;@override State<Activities>createState()=>_ActivitiesState();}class _ActivitiesState extends State<Activities> with WidgetsBindingObserver{late Future<List<dynamic>> load;SyncState sync=SyncState.sent;@override void initState(){super.initState();WidgetsBinding.instance.addObserver(this);load=widget.api.activities();replay();}@override void dispose(){WidgetsBinding.instance.removeObserver(this);super.dispose();}@override void didChangeAppLifecycleState(AppLifecycleState s){if(s==AppLifecycleState.resumed)replay();}Future<void>replay()async{setState(()=>sync=SyncState.sending);final result=await Queue.replay(widget.api);if(mounted)setState(()=>sync=result);}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Activities')),body:FutureBuilder<List<dynamic>>(future:load,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator(semanticsLabel:'Loading activities'));if(s.hasError)return Center(child:FilledButton(onPressed:()=>setState(()=>load=widget.api.activities()),child:const Text('Try again')));final rows=s.data??[];if(rows.isEmpty)return const Center(child:Text('There are no activities to complete right now.'));final label={SyncState.waiting:'Saved on this device — waiting to send',SyncState.sending:'Sending saved responses…',SyncState.sent:'',SyncState.needsAttention:'Saved responses need attention. Please sign in again.'}[sync]!;return RefreshIndicator(onRefresh:()async{await replay();setState(()=>load=widget.api.activities());},child:ListView(children:[if(label.isNotEmpty)Semantics(liveRegion:true,child:Padding(padding:const EdgeInsets.all(12),child:Text(label))),...rows.map((r)=>ListTile(title:Text(r['title']??'Activity'),subtitle:Text(r['availability']?['status']??'Available'),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>TextActiv